css:
.loader {
  padding: 5px;
  width: 150px;
  height: 70px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #fff;
  filter: blur(4px) contrast(12);
}

.loader:before {
  content: "";
  height: 40px;
  border-top: 9px solid black;
  border-bottom: 9px solid black;
  border-right: 9px solid black;
  border-left: 9px solid black;
  aspect-ratio: 3;
  --c: #0000 64%, #000 66% 98%, #0000 101%;
  background:
    radial-gradient(35% 146% at 50% 159%, var(--c)) 0 0,
    radial-gradient(35% 146% at 50% -59%, var(--c)) 100% 100%;
  background-size: calc(200% / 4) 50%;
  background-repeat: repeat-x;
  animation: l11 0.8s infinite linear;
}

@keyframes l11 {
  to {
    background-position:
      -200% 0,
      -100% 100%;
  }
}
.loader-box {
  position: relative;
  display: inline-grid;
  isolation: isolate;
  overflow: hidden;
  background: #fff;
  border-radius: 16px;
}

.loader-box .tint {
  position: absolute;
  inset: 0;
  mix-blend-mode: lighten;
  pointer-events: none;
  animation: tint 10.5s ease-in-out infinite;
  /* 1.5s per color */
}
@keyframes tint {
  0%,
  6% {
    background: oklch(0.68 0.21 25);
  }

  /* coral  */
  14.29%,
  20.29% {
    background: oklch(0.72 0.13 200);
  }

  /* teal   */
  28.57%,
  34.57% {
    background: oklch(0.6 0.22 300);
  }

  /* violet */
  42.86%,
  48.86% {
    background: oklch(0.78 0.16 65);
  }

  /* orange */
  57.14%,
  63.14% {
    background: oklch(0.72 0.19 150);
  }

  /* green  */
  71.43%,
  77.43% {
    background: oklch(0.62 0.2 255);
  }

  /* blue   */
  85.71%,
  91.71% {
    background: oklch(0.68 0.22 350);
  }

  /* pink   */
  100% {
    background: oklch(0.68 0.21 25);
  }
}

/* fallback for browsers without oklch() */
@supports not (color: oklch(0.5 0.1 100)) {
  @keyframes tint {
    0%,
    6% {
      background: #f5525b;
    }

    14.29%,
    20.29% {
      background: #00b3bd;
    }

    28.57%,
    34.57% {
      background: #9a5cf0;
    }

    42.86%,
    48.86% {
      background: #f7a13d;
    }

    57.14%,
    63.14% {
      background: #34c96c;
    }

    71.43%,
    77.43% {
      background: #3d7bff;
    }

    85.71%,
    91.71% {
      background: #f05aa8;
    }

    100% {
      background: #f5525b;
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .loader-box .tint {
    animation-duration: 42s;
  }
}
